      for(let i=0;i<count;i++){const s=(i+shift)*profile.length/count;if(s>.001&&s<profile.length-.001)points.push(s);}
      points.sort((a,b)=>a-b);return points.slice(0,-1).map((x,i)=>[x,points[i+1]]).filter(([a,b])=>b-a>.0001);
