      const margin=.0028,top=.157+rand(idx)*.008;
      const rings=[[.005,.072],[.001,.109],[.006,.135],[.017,top-.006],[.038,top],[.245,top-.005],[.269,top-.014],[.279,.127],[.278,.103],[.016,.072]];
